import {mountLayeredArt} from 'preview/layered-art.js';
import {createBlossomRig} from 'jz/js/blossom-rig.js';
import {mountNightCrowTitle} from 'jz/js/night-crow-title.js';
const OFFLINE_TEXTURES={"banner-cloth": "data:image/webp;base64,", "wood": "data:image/webp;base64,", "cloth": "data:image/webp;base64,"};
import * as THREE from 'jz/vendor/three.module.js';
import {Banner} from 'jz/js/cloth.js';
import {createEmbers} from 'jz/js/embers.js';
import {environment} from 'jz/js/environment.js';
import {particles} from 'jz/js/particles.js';
import {CameraPath} from 'jz/js/camera.js';

export async function createScene(canvas, onStage=()=>{}) {
 const renderer=new THREE.WebGLRenderer({canvas,antialias:true,alpha:false,powerPreference:'high-performance'});
 renderer.setPixelRatio(Math.min(devicePixelRatio,1.5));renderer.setSize(innerWidth,innerHeight);renderer.outputColorSpace=THREE.SRGBColorSpace;renderer.toneMapping=THREE.ACESFilmicToneMapping;renderer.toneMappingExposure=1.12;
 renderer.shadowMap.enabled=true;renderer.shadowMap.type=THREE.PCFSoftShadowMap;
 // Cache static architectural shadows. Animated flags update their vertex geometry.
 renderer.shadowMap.autoUpdate=false;renderer.shadowMap.needsUpdate=true;
 const scene=new THREE.Scene(),curtainScene=new THREE.Scene();
 const camera=new THREE.PerspectiveCamera(45,innerWidth/innerHeight,.2,380),curtainCamera=new THREE.PerspectiveCamera(42,innerWidth/innerHeight,.1,100);curtainCamera.position.z=20;
 onStage("renderer");
 const breathe=()=>new Promise(r=>setTimeout(r,0));
 await breathe();
 const loader=new THREE.TextureLoader();const load=async name=>{const tex=await loader.loadAsync(OFFLINE_TEXTURES[name]);tex.colorSpace=THREE.SRGBColorSpace;onStage("texture-"+name);return tex;};
 // Photographic sky/mountains/pagodas/midground are no longer loaded or rendered.
 const textures=await Promise.all(['banner-cloth','wood','cloth'].map(load));const [cloth,wood,weave]=textures;
 await breathe();
 const env=environment(scene,{cloth,wood}),snow=particles(scene),banner=new Banner(curtainScene,cloth,weave),embers=createEmbers(curtainScene,banner),path=new CameraPath(camera);
 onStage("geometry");await breathe();
 await mountNightCrowTitle(scene);onStage("title");await breathe();
 const layered=await mountLayeredArt(scene);onStage("art");
 const blossomRig=createBlossomRig(scene);
 let disposed=false,clothReleased=false,explore=false,dragging=false,px=0,py=0;
 const target=new THREE.Vector3(0,4,-14),offset=new THREE.Vector3(),orbit=new THREE.Spherical();
 const resize=()=>{const a=innerWidth/innerHeight;camera.aspect=a;camera.updateProjectionMatrix();curtainCamera.aspect=a;curtainCamera.updateProjectionMatrix();renderer.setPixelRatio(Math.min(devicePixelRatio,1.5));renderer.setSize(innerWidth,innerHeight);const height=2*Math.tan(THREE.MathUtils.degToRad(21))*20*1.22;banner.mesh.scale.set(height*a/14,height/10,1);banner.uniforms.uAspect.value=a;};
 const down=e=>{if(!explore||e.button!==0||e.target.closest('a,button,dialog'))return;dragging=true;px=e.clientX;py=e.clientY;};
 const move=e=>{if(!dragging)return;orbit.theta-=(e.clientX-px)*.004;orbit.phi=THREE.MathUtils.clamp(orbit.phi+(e.clientY-py)*.004,.24,1.50);px=e.clientX;py=e.clientY;};
 const up=()=>{dragging=false;};
 const wheel=e=>{if(!explore||e.target.closest('dialog'))return;e.preventDefault();orbit.radius=THREE.MathUtils.clamp(orbit.radius*Math.exp(e.deltaY*.001),14,105);};
 const key=e=>{if(!explore||e.target.closest('input,textarea,dialog'))return;const k=e.key;if(k==='ArrowLeft')orbit.theta-=.10;else if(k==='ArrowRight')orbit.theta+=.10;else if(k==='ArrowUp')orbit.phi=Math.max(.24,orbit.phi-.06);else if(k==='ArrowDown')orbit.phi=Math.min(1.50,orbit.phi+.06);else if(k==='+')orbit.radius=Math.max(14,orbit.radius-3);else if(k==='-')orbit.radius=Math.min(105,orbit.radius+3);else return;e.preventDefault();};
 resize();addEventListener('resize',resize);addEventListener('pointerdown',down);addEventListener('pointermove',move);addEventListener('pointerup',up);addEventListener('pointercancel',up);addEventListener('keydown',key);addEventListener('wheel',wheel,{passive:false});
 const api={camera:curtainCamera,banner,
 seek(value){path.seek(value);},
 async prepare(){path.opening();if(renderer.compileAsync){await renderer.compileAsync(scene,camera);await renderer.compileAsync(curtainScene,curtainCamera);}else{renderer.compile(scene,camera);renderer.compile(curtainScene,curtainCamera);}onStage("shaders");},
  setExplore(value){explore=value;dragging=false;if(value){target.set(0,camera.position.z>45?2:4,camera.position.z>45?55:-14);offset.subVectors(camera.position,target);orbit.setFromVector3(offset);}return explore;},
  render(t,p,progress,dt,nudge,mx=0,my=0,approach=0){if(disposed)return;const journey=p>=1;
   if(journey){if(explore){camera.position.copy(offset.setFromSpherical(orbit).add(target));camera.lookAt(target);}else path.update(progress,dt,mx,my,approach);if(!clothReleased){banner.dispose();embers.dispose();clothReleased=true;}}
   else{path.opening(Math.max(0,p));banner.update(t,p,dt);embers.update(p);}
   layered.update(progress);env.update(t);blossomRig.update(t);snow(t,camera,dt);renderer.autoClear=false;renderer.clear();renderer.render(scene,camera);if(!journey){renderer.clearDepth();renderer.render(curtainScene,curtainCamera);}
  },
  dispose(){if(disposed)return;disposed=true;removeEventListener('resize',resize);removeEventListener('pointerdown',down);removeEventListener('pointermove',move);removeEventListener('pointerup',up);removeEventListener('pointercancel',up);removeEventListener('wheel',wheel);removeEventListener('keydown',key);banner.dispose();if(!clothReleased)embers.dispose();layered.dispose();blossomRig.dispose();snow.dispose?.();env.dispose();scene.traverse(o=>{o.geometry?.dispose();if(o.material)for(const m of Array.isArray(o.material)?o.material:[o.material])m.dispose();});for(const tex of textures)tex.dispose();renderer.dispose();if(window.__JZ3D?.scene===scene)delete window.__JZ3D;}
 };
 // Real scene graph for inspection and QA; no simulated model/FPS counters.
 window.__JZ3D={scene,camera,renderer,environment:env,path,setExplore:api.setExplore,snapshot(){let meshes=0,instances=0,vertices=0;scene.traverse(o=>{if(o.isMesh){meshes++;instances+=o.isInstancedMesh?o.count:1;vertices+=(o.geometry.attributes.position?.count||0)*(o.isInstancedMesh?o.count:1);}});return {meshes,instances,vertices,camera:camera.position.toArray(),moon:env.moon.position.toArray(),frame:renderer.info.render.frame,drawCalls:renderer.info.render.calls,triangles:renderer.info.render.triangles,textures:renderer.info.memory.textures,explore};}};
 return api;
}
